async (sock, msg, from, args, msgInfoObj) => {
 const { sendMessageWTyping } = msgInfoObj;
 const greetings = [
 "Hello there! 👋",
 "Hey! How's it going? 😊",
 "Greetings, friend! 🤖",
 "Hi! Nice to see you! ✨",
 "Hello, world! 🌍"
 ];
 const pick = greetings[Math.floor(Math.random() * greetings.length)];
 return sendMessageWTyping(from, { text: pick }, { quoted: msg });
 }
